<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAuthStore} from '../stores/auth.js'
import {apiGet,apiRequest} from '../services/api.js'
import {formatarNumero as num,formatarPercentual as pct,formatarData as date,formatarDataHora as stamp} from '../utils/format.js'
import {download} from '../utils/download.js'
import CampaignExperimentEditor from '../components/CampaignExperimentEditor.vue'
const auth=useAuthStore(),route=useRoute(),router=useRouter(),items=ref([]),selected=ref(null),error=ref(''),creating=ref(false),parent=ref(null),initial=ref({}),decision=ref('maintain'),justification=ref(''),busy=ref(false)
let timer,running=false
const canManage=computed(()=>['admin','nurse'].includes(auth.user.role))
const metricLabels={response:'Resposta em 72h',on_time:'Retorno no prazo',attendance:'Comparecimento',checkin:'Check-in respondido',adherence:'Adesão ao plano'}
async function load(){if(running)return;running=true;try{items.value=await apiGet('/experiments');selected.value=items.value.find(c=>c.id===Number(route.params.id||route.query.experiment))||null;error.value=''}catch(e){error.value=e.message}finally{running=false}}
function choose(c){router.push('/campaign-management/'+c.id);creating.value=false}
function version(c){parent.value=c.id;initial.value={...c.data,name:c.name+' v'+(c.version+1),cycle:'Ciclo '+(c.version+1),...Object.fromEntries(Object.entries(c.data.criteria||{}).map(([k,v])=>['filter_'+k,v]))};creating.value=true}
async function saveDecision(){busy.value=true;try{await apiRequest('/experiments/'+selected.value.id+'/decision','POST',{decision:decision.value,justification:justification.value});justification.value='';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function start(c){try{await apiRequest('/experiments/'+c.id+'/start','POST');await load()}catch(e){error.value=e.message}}
async function exportCsv(){try{download((await apiGet('/experiments/export')).csv,'metricas-campanhas.csv')}catch(e){error.value=e.message}}
watch(()=>route.fullPath,load);onMounted(()=>{load();timer=setInterval(load,2000)});onBeforeUnmount(()=>clearInterval(timer))
const stage=k=>({sent:'Enviadas',read:'Lidas (simulação)',responded:'Responderam',scheduled:'Agendaram',attended:'Compareceram',invited:'Convidados',interested:'Interesse',welcomed:'Acolhidos',participating:'Participando',completed:'Concluídos'})[k]||k
</script>
<template><p class="eyebrow">SIMULAÇÃO · ENGAJAMENTO COM AVALIAÇÃO</p><div class="section-heading"><h1>Campanhas: medir e decidir</h1><div v-if="canManage" class="d-flex gap-2"><button class="btn btn-success" @click="creating=!creating;parent=null;initial={}">Nova campanha</button><button class="btn btn-outline-success" @click="exportCsv">Exportar métricas CSV</button></div></div><p v-if="error" role="alert" class="alert alert-danger">{{error}}</p><CampaignExperimentEditor v-if="creating&&canManage" :parent-id="parent" :initial="initial" @saved="load"/>
<div class="row g-3 mb-3"><div v-for="c in items" :key="c.id" class="col-md-6 col-xl-4"><button class="card card-body h-100 text-start w-100 campaign-card" :data-demo="'campanha-'+c.id" @click="choose(c)"><strong class="h5">{{c.name}}</strong><template v-if="c.data"><small>{{c.kind}} · {{date(c.data.measurement_from)}} a {{date(c.data.measurement_to)}}</small><span>{{metricLabels[c.data.main_metric]}}</span><span v-if="c.statistics">Efeito {{num(c.statistics.effect_pp,1)}} pontos ({{num(c.statistics.lower_pp,1)}} a {{num(c.statistics.upper_pp,1)}})</span><small v-if="c.statistics">Custo por retorno: {{c.statistics.cost_per_recovered===null?'sem ganho':'R$ '+num(c.statistics.cost_per_recovered,2)}}</small><span class="soft-tag mt-2 align-self-start" :data-demo="'selo-decisao-'+c.id">{{c.decision.label}}</span><small>{{c.data.history?'Histórico simulado':'Calculado nesta visita'}}</small></template><p v-else>{{c.suppressed?'grupo pequeno demais para exibir':c.participation.invited+' pessoas no público'}}</p></button></div></div><p v-if="!items.length">Nenhuma campanha de avaliação nesta base. Os ciclos educativos existentes continuam abaixo.</p>
<section v-if="selected&&canManage" class="card card-body mb-3" data-demo="campanha-detalhe"><h2>{{selected.name}} · v{{selected.version}}</h2><p>{{selected.data.objective}}</p><p>Público congelado: {{selected.population}} · comparação: {{selected.data.comparison}}<span v-if="selected.data.comparison==='historical'"> · Atenção: comparação histórica é mais fraca.</span></p><p v-if="selected.suppressed">grupo pequeno demais para exibir</p><template v-else><p class="alert alert-info"><strong>{{selected.decision.label}}</strong> · {{selected.decision.why}} {{selected.diagnosis.suggestion}}</p><div class="row g-3"><div v-for="(funnel,variant) in selected.diagnosis.funnels" :key="variant" class="col-md-6"><h3 class="h5">Variante {{variant}}</h3><p v-for="(value,key) in funnel" :key="key" class="border-bottom py-1 mb-1">{{stage(key)}} <strong class="float-end">{{num(value)}}</strong></p></div></div><p class="mt-3">Maior queda: {{stage(selected.diagnosis.largest_drop.from)}} → {{stage(selected.diagnosis.largest_drop.to)}} · {{pct(selected.diagnosis.largest_drop.loss_percent)}}.</p><h3 class="h5">Segmentos · mínimo 10</h3><p v-for="segment in selected.diagnosis.segments" :key="segment.name">{{segment.name}}: {{pct(segment.rate)}} entre {{segment.n}} pessoas <strong v-if="segment.below_average">· pelo menos 10 pontos abaixo da média</strong></p><p v-if="!selected.diagnosis.segments.length">Sem segmentos apuráveis com grupo mínimo.</p>
<details class="mt-3"><summary>Como calculamos · taxas, custo e limites</summary><p class="mt-2">Resposta em 72h: {{pct(selected.statistics.response_percent)}} · mediana: {{num(selected.statistics.median_response_hours,1)}} horas. Confirmou ou remarcou ÷ N: {{pct(selected.statistics.scheduling_percent)}}. Compareceu ÷ agendados: {{pct(selected.statistics.attendance_percent)}}.</p><p>Retorno no prazo: {{pct(selected.statistics.on_time_percent)}} · check-in: {{pct(selected.statistics.checkin_percent)}} · adesão: {{pct(selected.statistics.adherence_percent)}}. Saídas: {{pct(selected.statistics.optout_percent)}} · satisfação: {{pct(selected.statistics.satisfaction_percent)}} · queixa procedente no cenário: {{selected.statistics.upheld_pressure?'sim':'não'}}.</p><p>Efeito = taxa A − taxa B. IC95% = diferença ± 1,96 × √(pA(1−pA)/nA + pB(1−pB)/nB). Amostra por grupo ≈ 7,84 × soma das variâncias ÷ meta²: {{num(selected.statistics.sample_per_arm)}}.</p><p>Custo = mensagens × custo unitário + resgates × benefício + horas × custo da hora. Total R$ {{num(selected.statistics.cost_total,2)}}. Custo por retorno = total ÷ retornos acima do esperado; sem ganho, não há custo por retorno recuperado.</p><p>Um ganho de 4 pontos sobre uma base de cerca de 50% exige aproximadamente 2400 pessoas por grupo. Contato: 30 dias; incentivo: trimestre/semestre; risco: 6 a 12 meses, separado do julgamento de campanhas de contato. Incentivo reconhece participação, nunca resultado de saúde.</p></details></template>
<button v-if="selected.status==='planned'" class="btn btn-outline-success mt-3" @click="start(selected)">Iniciar e congelar público</button><button class="btn btn-outline-success mt-3" @click="version(selected)">Criar nova versão</button><form class="border-top mt-3 pt-3" @submit.prevent="saveDecision"><h3 class="h5">Registrar decisão da coordenação</h3><label for="campaign-decision">Decisão</label><select id="campaign-decision" v-model="decision" class="form-select mb-2"><option value="maintain">Manter</option><option value="adjust">Ajustar</option><option value="redesign">Redesenhar</option><option value="end">Encerrar</option><option value="pause">Pausar e revisar</option><option value="wait">Aguardar dados</option></select><label for="campaign-why">Justificativa</label><textarea id="campaign-why" v-model="justification" required maxlength="1500" class="form-control mb-2"/><button class="btn btn-success" :disabled="busy">Registrar decisão</button></form><div v-for="(d,i) in selected.decisions" :key="i" class="border-top py-2 mt-2">{{d.decision}} · {{d.author}} · {{stamp(d.created_at)}}<p>{{d.justification}}</p></div><p v-if="selected.parent_id" class="mt-2">Derivada da campanha #{{selected.parent_id}}. Compare os cartões preservando o histórico.</p></section></template>
<style scoped>.campaign-card{color:inherit;border:1px solid #d6e3df}.campaign-card:hover{border-color:#087666}</style>